<?php
require_once __DIR__.'/accounting-core.php';
class CoOperations {
 private $s;
 public function __construct(CoService $service){$this->s=$service;}
 public function bank($company,array $p){$this->s->permit($company,'manage');return $this->s->transaction(function()use($company,$p){$currency=$p['currency']??'PEN';if(!in_array($currency,['PEN','USD','EUR'],true))throw new InvalidArgumentException('Moneda inválida.');$legacy=empty($p['legacyId'])?null:(int)$p['legacyId'];if($legacy&&$currency!=='PEN')throw new InvalidArgumentException('La caja ERP no registra moneda por movimiento. Solo se vinculan cuentas PEN; importa USD/EUR como extractos y asientos revisados.');if($legacy&&!$this->s->one('SELECT IdCuenta FROM Cb_Cuenta WHERE IdCuenta=? AND COALESCE(Anulado,0)=0',[$legacy]))throw new InvalidArgumentException('Cuenta ERP no disponible.');$code=coText((string)($p['account']??''),20,true);$a=$this->s->one("SELECT Code FROM Co_Account WHERE CompanyId=? AND Code=? AND ReportGroup IN ('bank','cash') AND Active=1 AND Postable=1",[$company,$code]);if(!$a)throw new InvalidArgumentException('Selecciona una cuenta bancaria contable habilitada.');if($this->s->one('SELECT Id FROM Co_Bank WHERE CompanyId=? AND Account=?',[$company,$code]))throw new InvalidArgumentException('Usa una subcuenta contable independiente por cada banco.');$this->s->exec('INSERT INTO Co_Bank(CompanyId,Name,Number,Currency,Account,LegacyId) VALUES(?,?,?,?,?,?)',[$company,coText($p['name']??'',120,true),coText($p['number']??'',80,true),$currency,$code,empty($p['legacyId'])?null:(int)$p['legacyId']]);$id=$this->s->db->lastInsertId();$this->s->audit($company,'create','bank',$id);return ['id'=>$id];});}
 public function importBank($company,array $p){$this->s->permit($company,'reconcile');$bank=$this->s->one('SELECT * FROM Co_Bank WHERE CompanyId=? AND Id=?',[$company,(int)($p['bankId']??0)]);$rows=$p['rows']??[];if(!$bank||!is_array($rows)||!count($rows)||count($rows)>10000)throw new InvalidArgumentException('Banco o archivo inválido.');return $this->s->transaction(function()use($company,$bank,$rows){$added=0;$duplicates=0;foreach($rows as $r){$id=coText((string)($r['id']??''),120,true);$date=coDate($r['date']??'');$amount=coMoney($r['amount']??'',true);$memo=coText($r['memo']??'',500);if(!$amount)throw new InvalidArgumentException('Movimiento bancario sin importe.');$hash=hash('sha256',coJson([$id,$date,$amount,$memo]));$existing=$this->s->one('SELECT Hash FROM Co_BankItem WHERE CompanyId=? AND BankId=? AND ExternalId=?',[$company,$bank['Id'],$id]);if($existing){if($existing['Hash']!==$hash)throw new InvalidArgumentException('El mismo identificador bancario contiene datos distintos.');$duplicates++;continue;}$this->s->exec('INSERT INTO Co_BankItem(CompanyId,BankId,ExternalId,ItemDate,Memo,Amount,Hash) VALUES(?,?,?,?,?,?,?)',[$company,$bank['Id'],$id,$date,$memo,$amount,$hash]);$added++;}$this->s->audit($company,'import','bank',$bank['Id'],['added'=>$added,'duplicates'=>$duplicates]);return ['added'=>$added,'duplicates'=>$duplicates];});}
 public function match($company,array $p){$this->s->permit($company,'reconcile');return $this->s->transaction(function()use($company,$p){$i=$this->s->one('SELECT i.*,b.Account,b.Currency FROM Co_BankItem i JOIN Co_Bank b ON b.CompanyId=i.CompanyId AND b.Id=i.BankId WHERE i.CompanyId=? AND i.Id=? FOR UPDATE',[$company,(int)($p['bankItemId']??0)]);if(!$i)throw new InvalidArgumentException('Movimiento no disponible.');
  if(!empty($p['unmatch'])){$this->s->exec('DELETE FROM Co_BankMatch WHERE CompanyId=? AND BankItemId=?',[$company,$i['Id']]);$this->s->audit($company,'unmatch','bank-item',$i['Id'],['reason'=>coText($p['reason']??'',500,true)]);return ['saved'=>true];}
  $l=$this->s->one("SELECT l.*,e.Currency FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId WHERE l.CompanyId=? AND l.Id=? AND e.Status='posted' FOR UPDATE",[$company,(int)($p['lineId']??0)]);if(!$l||$l['Account']!==$i['Account']||$l['Currency']!==$i['Currency'])throw new InvalidArgumentException('La línea no corresponde a la empresa, cuenta o moneda.');
  $usedBank=(int)$this->s->one('SELECT COALESCE(SUM(Amount),0) Amount FROM Co_BankMatch WHERE CompanyId=? AND BankItemId=?',[$company,$i['Id']])['Amount'];$usedLine=(int)$this->s->one('SELECT COALESCE(SUM(Amount),0) Amount FROM Co_BankMatch WHERE CompanyId=? AND LineId=?',[$company,$l['Id']])['Amount'];$bankRemaining=(int)$i['Amount']-$usedBank;$lineRemaining=(int)$l['OriginalDebit']-(int)$l['OriginalCredit']-$usedLine;$amount=isset($p['amount'])&&$p['amount']!==''?coMoney($p['amount'],true):($bankRemaining<0?-1:1)*min(abs($bankRemaining),abs($lineRemaining));if(!$amount||($amount>0)!==($bankRemaining>0)||($amount>0)!==($lineRemaining>0)||abs($amount)>abs($bankRemaining)||abs($amount)>abs($lineRemaining))throw new InvalidArgumentException('La asociación excede el saldo pendiente o tiene signo incompatible.');
  $this->s->exec('INSERT INTO Co_BankMatch(CompanyId,BankItemId,LineId,Amount,Username,CreatedAt) VALUES(?,?,?,?,?,?)',[$company,$i['Id'],$l['Id'],$amount,$this->s->user,coNow()]);$this->s->audit($company,'match','bank-item',$i['Id'],['line'=>$l['Id'],'amount'=>$amount]);return ['saved'=>true];});}
 public function statement($company,array $p){$this->s->permit($company,'reconcile');$bank=(int)($p['bankId']??0);if(!$this->s->one('SELECT Id FROM Co_Bank WHERE CompanyId=? AND Id=?',[$company,$bank]))throw new InvalidArgumentException('Banco de otra empresa.');$from=coDate($p['from']??'');$to=coDate($p['to']??'');if($from>$to)throw new InvalidArgumentException('Rango inválido.');$opening=coMoney($p['opening']??'',true);$closing=coMoney($p['closing']??'',true);$ref=coText($p['reference']??'',200,true);return $this->s->transaction(function()use($company,$bank,$from,$to,$opening,$closing,$ref,$p){$old=$this->s->one('SELECT * FROM Co_BankStatement WHERE CompanyId=? AND BankId=? AND DateFrom=? AND DateTo=? FOR UPDATE',[$company,$bank,$from,$to]);if($old&&(int)$old['Version']!==(int)($p['version']??0))throw new InvalidArgumentException('El extracto cambió. Recarga.');$this->s->exec('INSERT INTO Co_BankStatement(CompanyId,BankId,DateFrom,DateTo,Opening,Closing,Reference) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Opening=VALUES(Opening),Closing=VALUES(Closing),Reference=VALUES(Reference),Version=Version+1',[$company,$bank,$from,$to,$opening,$closing,$ref]);$this->s->audit($company,'statement','bank',$bank,['from'=>$from,'to'=>$to,'before'=>$old,'opening'=>$opening,'closing'=>$closing,'reference'=>$ref]);return ['saved'=>true];});}
 public function reconciliation($company,array $p){$this->s->permit($company);$id=(int)($p['bankId']??0);$bank=$this->s->one('SELECT * FROM Co_Bank WHERE CompanyId=? AND Id=?',[$company,$id]);if(!$bank)throw new InvalidArgumentException('Banco de otra empresa o inexistente.');$from=coDate($p['from']??substr(coNow(),0,7).'-01');$to=coDate($p['to']??substr(coNow(),0,10));if($from>$to)throw new InvalidArgumentException('Rango inválido.');
  $items=$this->s->rows('SELECT i.*,MIN(m.LineId) LineId,COALESCE(SUM(m.Amount),0) MatchedAmount,i.Amount-COALESCE(SUM(m.Amount),0) RemainingAmount FROM Co_BankItem i LEFT JOIN Co_BankMatch m ON m.CompanyId=i.CompanyId AND m.BankItemId=i.Id WHERE i.CompanyId=? AND i.BankId=? AND i.ItemDate BETWEEN ? AND ? GROUP BY i.Id ORDER BY i.ItemDate,i.Id',[$company,$id,$from,$to]);$ledger=$this->s->rows("SELECT l.Id,l.OriginalDebit,l.OriginalCredit,e.EntryDate,e.Document,e.Memo,MIN(m.BankItemId) BankItemId,COALESCE(SUM(m.Amount),0) MatchedAmount,l.OriginalDebit-l.OriginalCredit-COALESCE(SUM(m.Amount),0) RemainingAmount FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId LEFT JOIN Co_BankMatch m ON m.CompanyId=l.CompanyId AND m.LineId=l.Id WHERE l.CompanyId=? AND l.Account=? AND e.Currency=? AND e.Status='posted' AND e.EntryDate BETWEEN ? AND ? GROUP BY l.Id ORDER BY e.EntryDate,l.Id",[$company,$bank['Account'],$bank['Currency'],$from,$to]);$statement=array_sum(array_column($items,'Amount'));$book=0;foreach($ledger as $l)$book+=(int)$l['OriginalDebit']-(int)$l['OriginalCredit'];$statementData=$this->s->one('SELECT * FROM Co_BankStatement WHERE CompanyId=? AND BankId=? AND DateFrom=? AND DateTo=?',[$company,$id,$from,$to]);$balance=$this->s->one("SELECT COALESCE(SUM(l.OriginalDebit-l.OriginalCredit),0) Amount FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId WHERE l.CompanyId=? AND l.Account=? AND e.Currency=? AND e.Status='posted' AND e.EntryDate<?",[$company,$bank['Account'],$bank['Currency'],$from]);$opening=(int)$balance['Amount'];return ['bank'=>$bank,'items'=>$items,'ledger'=>$ledger,'periodStatementMovement'=>$statement,'periodBookMovement'=>$book,'difference'=>$statement-$book,'statement'=>$statementData,'bookOpening'=>$opening,'bookClosing'=>$opening+$book,'closingDifference'=>$statementData?(int)$statementData['Closing']-$opening-$book:null,'statementArithmeticDifference'=>$statementData?(int)$statementData['Opening']+$statement-(int)$statementData['Closing']:null,'note'=>$statementData?'Saldos comparados con el extracto identificado. Revisa movimientos faltantes y partidas en tránsito.':'Falta registrar el saldo inicial y final del extracto. No se presume saldo cero.'];}
 public function asset($company,array $p){$this->s->permit($company,'draft');$cost=coMoney($p['cost']??'');$residual=coMoney($p['residual']??'0');$months=filter_var($p['lifeMonths']??0,FILTER_VALIDATE_INT);if(!$cost||$residual>=$cost||!$months||$months<1||$months>1200)throw new InvalidArgumentException('Costo, residual o vida útil inválidos.');$branch=empty($p['branchId'])?null:(int)$p['branchId'];if($branch&&!$this->s->one('SELECT Id FROM Co_Branch WHERE CompanyId=? AND Id=?',[$company,$branch]))throw new InvalidArgumentException('Sucursal no disponible.');foreach(['expenseAccount'=>'depreciation','accumulatedAccount'=>'accumulated_depreciation'] as $k=>$group)if(!$this->s->one('SELECT Code FROM Co_Account WHERE CompanyId=? AND Code=? AND ReportGroup=? AND Active=1 AND Postable=1',[$company,$p[$k]??'',$group]))throw new InvalidArgumentException('Cuenta de depreciación no disponible.');return $this->s->transaction(function()use($company,$p,$cost,$residual,$months,$branch){$this->s->exec('INSERT INTO Co_Asset(CompanyId,BranchId,Name,StartDate,Cost,Residual,LifeMonths,ExpenseAccount,AccumulatedAccount) VALUES(?,?,?,?,?,?,?,?,?)',[$company,$branch,coText($p['name']??'',160,true),coDate($p['startDate']??''),$cost,$residual,$months,$p['expenseAccount'],$p['accumulatedAccount']]);$id=$this->s->db->lastInsertId();$this->s->audit($company,'create','asset',$id);return ['id'=>$id];});}
 public function depreciation($company,array $p){$this->s->permit($company,'draft');$period=coPeriod($p['period']??'');$a=$this->s->one('SELECT * FROM Co_Asset WHERE CompanyId=? AND Id=?',[$company,(int)($p['assetId']??0)]);if(!$a)throw new InvalidArgumentException('Activo no disponible.');$start=substr($a['StartDate'],0,7);$offset=((int)substr($period,0,4)-(int)substr($start,0,4))*12+(int)substr($period,5,2)-(int)substr($start,5,2);if($offset<0||$offset>=(int)$a['LifeMonths'])throw new InvalidArgumentException('Período fuera de la vida útil.');$base=(int)$a['Cost']-(int)$a['Residual'];$amount=intdiv($base,(int)$a['LifeMonths'])+($offset<$base%(int)$a['LifeMonths']?1:0);return $this->s->draft($company,['date'=>(new DateTime($period.'-01'))->format('Y-m-t'),'currency'=>'PEN','rate'=>'1','branchId'=>$a['BranchId'],'memo'=>'Depreciación lineal: '.$a['Name'],'sourceType'=>'depreciation','sourceId'=>$a['Id'].':'.$period,'lines'=>[['account'=>$a['ExpenseAccount'],'debit'=>coAmount($amount),'credit'=>'0'],['account'=>$a['AccumulatedAccount'],'debit'=>'0','credit'=>coAmount($amount)]]]);}
 public function template($company,array $p){$c=$this->s->permit($company,'draft');$map=$c['settings']['accounts']??[];$kind=$p['kind']??'';$amount=coMoney($p['amount']??'');if(!$amount)throw new InvalidArgumentException('Importe requerido.');$debit='';$credit='';$cash=false;
  $types=['supplier_refund'=>['bank','payable',true],'customer_refund'=>['receivable','bank',true],'withholding_received'=>['withholding_credit','receivable',false],'withholding_paid'=>['payable','withholding_payable',false],'detraction_received'=>['restricted_bank','receivable',true],'detraction_paid'=>['payable','bank',true],'perception_remittance'=>['perception_payable','bank',true],'customer_receipt'=>['cash','receivable',true],'supplier_payment'=>['payable','bank',true],'cash_income'=>['cash','other_income',true],'cash_expense'=>['expense','cash',true],'bank_income'=>['bank','receivable',true],'bank_expense'=>['bank_fees','bank',true],'inventory_in'=>['inventory','inventory_adjustment',false],'inventory_out'=>['inventory_loss','inventory',false],'cost_of_sales'=>['cost_goods','inventory',false],'expense_accrual'=>['expense','payable',false],'payroll_accrual'=>['payroll','payroll_payable',false],'payroll_payment'=>['payroll_payable','bank',true]];
  if(!isset($types[$kind]))throw new InvalidArgumentException('Tipo de operación no disponible.');list($debit,$credit,$cash)=$types[$kind];$debitAccount=$map[$debit]??'';$creditAccount=$map[$credit]??'';
  $lines=[['account'=>$debitAccount,'debit'=>coAmount($amount),'credit'=>'0','partyType'=>$p['partyType']??'','partyId'=>$p['partyId']??''],['account'=>$creditAccount,'debit'=>'0','credit'=>coAmount($amount),'partyType'=>$p['partyType']??'','partyId'=>$p['partyId']??'']];
  if($cash){$flow=$p['cashFlow']??'operating';foreach($lines as &$l)if(in_array($l['account'],[$map['cash']??null,$map['bank']??null,$map['restricted_bank']??null],true))$l['cashFlow']=$flow;unset($l);}
  return $this->s->draft($company,['date'=>$p['date']??'','branchId'=>$p['branchId']??null,'currency'=>$p['currency']??'PEN','rate'=>$p['rate']??'1','memo'=>coText($p['memo']??'',500,true),'document'=>coText($p['document']??'',100),'sourceType'=>$kind,'sourceId'=>coText((string)($p['sourceId']??''),100,true),'lines'=>$lines]);
 }
}
